package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.model.client.CallContext;
import java.time.*;
import java.util.*;
import org.neo4j.driver.*;
import org.neo4j.driver.types.*;

/** Actual Go-compatible Neo4j/APOC namespace, graph writes and read evidence. */
public final class Neo4jGraphRepository implements GraphExtractionStore,AutoCloseable {
  private final Driver driver;private final ObjectMapper json;
  public Neo4jGraphRepository(Driver driver,ObjectMapper json){this.driver=driver;this.json=json;}
  public boolean enabled(){return driver!=null;}
  public static List<String> labels(String kb,String doc){var out=new ArrayList<String>();for(String label:List.of(kb,doc))if(!label.isEmpty())out.add("ENTITY"+label.replace('-','_'));return List.copyOf(out);}
  public void add(String kb,String doc,GraphExtractionText.Graph graph,CallContext call,Runnable guard){if(driver==null)throw new IllegalStateException("Neo4j graph storage is disabled");guard.run();call.check();
    var nodeData=new ArrayList<Map<String,Object>>();for(var n:graph.nodes()){var props=new LinkedHashMap<String,Object>();props.put("attributes",n.attributes());var row=new LinkedHashMap<String,Object>();row.put("name",n.name());row.put("knowledge_id",doc);row.put("props",props);row.put("chunks",n.chunks());row.put("labels",labels(kb,doc));nodeData.add(row);}
    var relationData=new ArrayList<Map<String,Object>>();for(var r:graph.relations()){var row=new LinkedHashMap<String,Object>();row.put("source",r.source());row.put("target",r.target());row.put("knowledge_id",doc);row.put("type",r.type());row.put("source_labels",labels(kb,doc));row.put("target_labels",labels(kb,doc));relationData.add(row);}
    Duration timeout=call.deadline()==null?Duration.ofMinutes(30):Duration.between(Instant.now(),call.deadline());if(timeout.isNegative()||timeout.isZero()){call.check();throw new IllegalStateException("Graph task deadline exceeded");}
    try(var session=driver.session(SessionConfig.builder().withDefaultAccessMode(AccessMode.WRITE).build())){session.executeWrite(tx->{guard.run();call.check();{
      tx.run("UNWIND $data AS row CALL apoc.merge.node(row.labels, {name: row.name, kg: row.knowledge_id}, row.props, {}) YIELD node SET node.chunks = apoc.coll.union(node.chunks, row.chunks) RETURN distinct 'done' AS result",Map.of("data",nodeData)).consume();guard.run();call.check();
      tx.run("UNWIND $data AS row CALL apoc.merge.node(row.source_labels, {name: row.source, kg: row.knowledge_id}, {}, {}) YIELD node as source CALL apoc.merge.node(row.target_labels, {name: row.target, kg: row.knowledge_id}, {}, {}) YIELD node as target CALL apoc.merge.relationship(source, row.type, {}, row.attributes, target) YIELD rel RETURN distinct 'done'",Map.of("data",relationData)).consume();guard.run();call.check();return null;
    }},TransactionConfig.builder().withTimeout(timeout).build());}
  }
  public void delete(String kb,String doc,CallContext call,Runnable guard){if(!enabled())return;if(kb.isEmpty()||doc.isEmpty())throw new IllegalArgumentException("document graph deletion requires a complete namespace");guard.run();call.check();Duration timeout=call.deadline()==null?Duration.ofSeconds(30):Duration.between(Instant.now(),call.deadline());if(timeout.isNegative()||timeout.isZero()){call.check();throw new IllegalStateException("Graph deletion deadline exceeded");}try(var session=driver.session(SessionConfig.builder().withDefaultAccessMode(AccessMode.WRITE).build())){session.executeWrite(tx->{long removed;do{guard.run();call.check();removed=tx.run("MATCH (n {kg:$doc}) WHERE all(label IN $labels WHERE label IN labels(n)) WITH n LIMIT 1000 DETACH DELETE n RETURN count(n) AS removed",Map.of("doc",doc,"labels",labels(kb,doc))).single().get("removed").asLong();guard.run();call.check();}while(removed==1000);return null;},TransactionConfig.builder().withTimeout(timeout).build());}}
  public GraphExtractionText.Graph search(String kb,String doc,List<String> names,CallContext call,Runnable guard){if(!enabled())return null;if(kb.isEmpty()&&doc.isEmpty())throw new IllegalArgumentException("graph search requires a namespace");guard.run();call.check();Duration timeout=call.deadline()==null?Duration.ofSeconds(30):Duration.between(Instant.now(),call.deadline());if(timeout.isNegative()||timeout.isZero()){call.check();throw new IllegalStateException("Graph search deadline exceeded");}String query="MATCH (n) WHERE all(label IN $labels WHERE label IN labels(n)) AND ($doc='' OR n.kg=$doc) AND ANY(nodeText IN $nodes WHERE n.name CONTAINS nodeText) AND EXISTS { (n)--() } WITH n, CASE WHEN n.name IN $nodes THEN 0 ELSE 1 END AS seed_rank, size(n.name) AS name_len, n.name AS name ORDER BY seed_rank,name_len,name,n.kg LIMIT $maxSeedNodes MATCH (n)-[r]-(m) WHERE all(label IN $labels WHERE label IN labels(m)) AND ($doc='' OR m.kg=$doc) WITH n,r,m,seed_rank,name_len,name ORDER BY seed_rank,name_len,name,n.kg,m.name,m.kg,type(r) LIMIT $maxRows RETURN n,r,m";try(var session=driver.session(SessionConfig.builder().withDefaultAccessMode(AccessMode.READ).build())){return session.executeRead(tx->{guard.run();call.check();var rows=tx.run(query,Map.of("labels",labels(kb,doc),"doc",doc,"nodes",names==null?List.of():names,"maxSeedNodes",200,"maxRows",2000));var nodes=new LinkedHashMap<String,GraphExtractionText.Node>();var relations=new ArrayList<GraphExtractionText.Relation>();int count=0;while(rows.hasNext()){var row=rows.next();Node n=row.get("n").asNode(),m=row.get("m").asNode();for(Node node:List.of(n,m)){String name=node.get("name").asString();nodes.putIfAbsent(name,new GraphExtractionText.Node(name,strings(node.get("attributes")),strings(node.get("chunks"))));}relations.add(new GraphExtractionText.Relation(n.get("name").asString(),m.get("name").asString(),row.get("r").asRelationship().type()));if(++count%256==0){guard.run();call.check();}}guard.run();call.check();return new GraphExtractionText.Graph(List.copyOf(nodes.values()),List.copyOf(relations));},TransactionConfig.builder().withTimeout(timeout).build());}}
  private static List<String> strings(Value values){return values.isNull()?List.of():values.asList(Neo4jGraphRepository::propertyString);}
  private static String propertyString(Value value){Object stored=value.asObject();if(stored instanceof String s)return s;if(stored instanceof Long n)return Long.toString(n);if(stored instanceof Double n)return GraphExtractionText.goFloat64(n);if(stored instanceof Boolean b)return Boolean.toString(b);return value.asString();}
  public ObjectNode counts(String kb,String doc){requireEnabled();try(var session=driver.session(SessionConfig.builder().withDefaultAccessMode(AccessMode.READ).build())){return session.executeRead(tx->{var record=tx.run("MATCH (n {kg: $knowledge_id}) WHERE all(label IN $labels WHERE label IN labels(n)) OPTIONAL MATCH (n)-[r]->(m {kg: $knowledge_id}) WHERE all(label IN $labels WHERE label IN labels(m)) RETURN count(DISTINCT n) AS entities, count(DISTINCT r) AS relations",Map.of("knowledge_id",doc,"labels",labels(kb,doc))).single();return json.createObjectNode().put("Entities",record.get("entities").asLong()).put("Relations",record.get("relations").asLong());},TransactionConfig.builder().withTimeout(Duration.ofSeconds(30)).build());}}
  public ObjectNode detail(String kb,String doc,String chunk){requireEnabled();try(var session=driver.session(SessionConfig.builder().withDefaultAccessMode(AccessMode.READ).build())){return session.executeRead(tx->{var rows=tx.run("MATCH (n {kg: $knowledge_id}) WHERE all(label IN $labels WHERE label IN labels(n)) AND $chunk_id IN coalesce(n.chunks, []) OPTIONAL MATCH (n)-[r]-(m {kg: $knowledge_id}) WHERE all(label IN $labels WHERE label IN labels(m)) RETURN n, r, startNode(r).name AS source, endNode(r).name AS target ORDER BY n.name, type(r)",Map.of("knowledge_id",doc,"labels",labels(kb,doc),"chunk_id",chunk));var out=json.createObjectNode();var nodes=out.putArray("nodes");var relations=out.putArray("relations");var nodeIds=new HashSet<String>();var relIds=new HashSet<String>();while(rows.hasNext()){var record=rows.next();Node n=record.get("n").asNode();if(nodeIds.add(n.elementId())){var row=nodes.addObject().put("id",n.elementId()).put("name",n.get("name").asString(""));row.set("labels",json.valueToTree(n.labels()));row.set("attributes",json.valueToTree(n.asMap()));row.set("chunk_ids",json.valueToTree(n.get("chunks").isNull()?null:n.get("chunks").asList(Value::asString)));}if(!record.get("r").isNull()){Relationship r=record.get("r").asRelationship();if(relIds.add(r.elementId())){var row=relations.addObject().put("id",r.elementId()).put("source",record.get("source").asString("")).put("target",record.get("target").asString("")).put("type",r.type());row.set("attributes",json.valueToTree(r.asMap()));}}}return out;},TransactionConfig.builder().withTimeout(Duration.ofSeconds(30)).build());}}
  private void requireEnabled(){if(driver==null)throw new IllegalStateException("Neo4j graph storage is disabled");}
  @Override public void close(){if(driver!=null)driver.close();}
}
